const pg = global.get('pg');
const dbConfig = global.get('dbConfig');
const client = new pg.Client({ ...dbConfig, connectionTimeoutMillis: 5000 });

try {
    await client.connect();
    const res = await client.query(
        'SELECT n.id, n.name, n.mac_address, n.location, n.room, n.status, n.last_seen, n.created_at, h.name AS hub_name FROM nodes n JOIN hubs h ON n.hub_id = h.id WHERE h.tenant_id = $1 ORDER BY n.created_at DESC;',
        msg.params
    );
    msg.payload = res.rows;
    return [msg, null];
} catch (err) {
    node.error('DB Error: ' + err.message, msg);
    msg.statusCode = 500;
    msg.payload = { error: 'Error de base de datos: ' + err.message };
    return [null, msg];
} finally {
    await client.end().catch(() => {});
}

