const jwt = global.get('jwt');
const jwtSecret = global.get('jwtSecret');
const auth = (msg.req.headers['authorization'] || '');
if (!auth.startsWith('Bearer ')) {
    msg.statusCode = 401;
    msg.payload = { error: 'No autorizado' };
    return [null, msg];
}
try {
    msg._user = jwt.verify(auth.slice(7), jwtSecret);
    return [msg, null];
} catch(e) {
    msg.statusCode = 401;
    msg.payload = { error: 'Token invalido o expirado' };
    return [null, msg];
}

// La accion viene en la ruta: /api/alarm/arm o /api/alarm/disarm
const action = (msg.req.params.action || '').toLowerCase();
if (action !== 'arm' && action !== 'disarm') {
    msg.statusCode = 400;
    msg.payload = { error: "Accion debe ser 'arm' o 'disarm'" };
    return [null, msg];
}

// Se busca el hub del tenant del usuario. El aislamiento multi-tenant
// lo garantiza el WHERE por tenant_id, nunca el cuerpo de la peticion.
msg.params = [msg._user.tenant_id];
msg.alarmAction = action;
return [msg, null];

const row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
if (!row || !row.serial_number) {
    msg.statusCode = 404;
    msg.payload = { error: 'No hay ningun hub registrado para este tenant' };
    return [null, msg];
}

const hubMac = String(row.serial_number).replace(/:/g, '').toLowerCase();
msg.topic = 'seguimiento360/tenant/' + row.tenant_id +
            '/site/'    + row.site_id  +
            '/hub/'     + hubMac       +
            '/command';

// El payload MQTT que recibe el hub.
msg.payload = JSON.stringify({
    action: msg.alarmAction,
    issued_by: msg._user.user_id,
    issued_at: new Date().toISOString()
});

// La respuesta HTTP viaja por la salida 2. Se clona el mensaje original
// (con msg.res y msg.req intactos) y solo se sustituye el payload: crear un
// objeto nuevo perderia msg.res y el nodo http response no podria contestar.
const respuesta = Object.assign({}, msg, {
    statusCode: 200,
    payload: {
        action: msg.alarmAction,
        hub_mac: hubMac,
        mqtt_topic: msg.topic,
        state: msg.alarmAction === 'arm' ? 'armed' : 'disarmed',
        message: 'Comando publicado al hub vía MQTT'
    }
});
return [msg, respuesta];

const webpush = global.get("webpush");
const fsMod   = global.get("fsPush");

let filas = msg.payload;
if (!Array.isArray(filas)) { filas = filas && filas.token ? [filas] : []; }
if (filas.length === 0) { node.warn("PUSH: sin dispositivos registrados"); return null; }

const p = msg.push || {};

// --- Titulo segun la gravedad ---
const ICONO = { critica: "\uD83D\uDEA8", media: "\u26A0\uFE0F", aviso: "\u2139\uFE0F" };
const ETIQUETA = { critica: "ALARMA", media: "AVISO", aviso: "INFO" };
const titulo = (ICONO[p.gravedad] || "") + " " + (ETIQUETA[p.gravedad] || "AVISO") +
               " \u2014 " + (p.habitacion || p.nodo || "Seguimiento 360");

// --- Cuerpo con los datos del evento ---
const partes = [];
partes.push(p.nodo || "sensor");
if (p.distancia != null) partes.push(p.distancia + " cm");
if (p.bateria != null) partes.push("bater\u00EDa " + p.bateria + "%");
if (p.ubicacion && p.ubicacion !== p.habitacion) partes.push(p.ubicacion);
const cuerpo = partes.join(" \u00B7 ");

// --- Vibracion: mas insistente en alarmas graves ---
const VIB = {
  critica: [400,150,400,150,400,150,400,150,400,150,800],
  media:   [250,120,250,120,250,120,500],
  aviso:   [200,100,200]
};

const aviso = {
  title: titulo,
  body: cuerpo,
  gravedad: p.gravedad || "aviso",
  vibrate: VIB[p.gravedad] || VIB.aviso,
  tag: "s360-" + (p.event || "evento"),
  url: "/portal/eventos.html"
};

const vapid = JSON.parse(fsMod.readFileSync("/data/vapid.json", "utf8"));
webpush.setVapidDetails("mailto:admin@seguimiento360.com", vapid.publicKey, vapid.privateKey);

const carga = JSON.stringify(aviso);
let enviados = 0;

filas.forEach(function (fila) {
  let sub;
  try { sub = typeof fila.token === "string" ? JSON.parse(fila.token) : fila.token; }
  catch (e) { node.error("PUSH token invalido: " + e.message); return; }

  webpush.sendNotification(sub, carga)
    .then(function (r) {
      enviados++;
      node.warn("PUSH OK " + r.statusCode + " (" + aviso.gravedad + ") -> " + aviso.title);
    })
    .catch(function (e) {
      // 404 y 410 significan que el navegador ya no existe: borrar el token
      if (e.statusCode === 404 || e.statusCode === 410) {
        node.warn("PUSH token caducado (" + e.statusCode + "), conviene borrarlo");
      } else {
        node.error("PUSH fallo " + e.statusCode + ": " + String(e.body).slice(0, 150));
      }
    });
});

return null;

const jwt = global.get('jwt');
const jwtSecret = global.get('jwtSecret');
const auth = (msg.req.headers['authorization'] || '');

if (!auth.startsWith('Bearer ')) {
    msg.statusCode = 401;
    msg.payload = { error: 'No autorizado' };
    return [null, msg];
}

let usuario;
try {
    usuario = jwt.verify(auth.slice(7), jwtSecret);
} catch (e) {
    msg.statusCode = 401;
    msg.payload = { error: 'Token inválido' };
    return [null, msg];
}

// El cuerpo trae la suscripcion del navegador
const cuerpo = msg.payload || {};
const suscripcion = cuerpo.subscription || cuerpo;

if (!suscripcion || !suscripcion.endpoint) {
    msg.statusCode = 400;
    msg.payload = { error: 'Falta la suscripción' };
    return [null, msg];
}

// El user_id sale del JWT, nunca del cuerpo (si no, cualquiera
// podria registrar un token a nombre de otro usuario).
const userId = usuario.user_id || usuario.id || null;
if (!userId) {
    msg.statusCode = 400;
    msg.payload = { error: 'El token no identifica al usuario' };
    return [null, msg];
}

const tenantId = usuario.tenant_id || null;
msg.params = [userId, tenantId, JSON.stringify(suscripcion)];
msg._usuario = userId;
return [msg, null];

// Un usuario puede tener varios dispositivos. Se guarda uno por
// endpoint: si vuelve el mismo navegador, se actualiza la fecha.
msg.queryParams = msg.params;
return msg;

msg.statusCode = 201;
msg.payload = { success: true, mensaje: "Dispositivo registrado para notificaciones" };
return msg;

msg.statusCode = msg.statusCode || 500;
msg.payload = msg.payload || { error: "Error al registrar el dispositivo" };
